// ─── Shared types ─────────────────────────────────────────────────────────────

export type DocActionType =
  | 'signature-unsigned'
  | 'signature-signed'
  | 'signature-rejected'
  | 'receipt-unread'
  | 'receipt-read'
  | 'share';

export type MeterStatus = 'unsigned' | 'signed';
export type MeterType   = 'electricity' | 'water' | 'gas';

export interface TenantInfo {
  firstName: string;
  lastName: string;
  email: string;
  countryCode: string;
  phone: string;
}

export interface UploadedFile {
  id: number;
  name: string;
  type: 'pdf' | 'image' | 'doc';
  size: string;
}

// ─── Contract detail types ────────────────────────────────────────────────────

export interface ContractDetail {
  id: number;
  actionType: DocActionType;
  subject: string;
  rentalPeriod: string;
  building: string;
  tenant: TenantInfo;
  uploadedFiles?: UploadedFile[];
  filePreview?: string;
  description: string;
  ackReadReceipt: boolean;
  ackSignature: boolean;
  sendViaLink: boolean;
  sendViaHausBuddy: boolean;
  sendViaEmail: boolean;
}

export const watermarkText: Record<DocActionType, string | null> = {
  'signature-unsigned': null,
  'signature-signed':   null,
  'receipt-unread':     'Awaiting read confirmation',
  'receipt-read':       null,
  'share':              null,
  'signature-rejected': null,
};

// ─── Meter reading types & data ───────────────────────────────────────────────

export const meterUnitMap: Record<MeterType, string> = {
  electricity: 'kWh',
  water:       'm³',
  gas:         'm³',
};

