  id: number;
  meterType: MeterType;
  status: MeterStatus;
  subject: string;
  rentalPeriod: string;
  building: string;
  tenant: TenantInfo;
  uploadedFiles: UploadedFile[];
  description: string;
  readingDate: string;
  readingTime: string;
  readingValue: string;
  ackSignature: boolean;
  sendViaHausBuddy: boolean;
  sendViaEmail: boolean;
